source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    top = min(r for r, _ in points)
    bottom = max(r for r, _ in points)
    left = min(c for _, c in points)
    right = max(c for _, c in points)
    out = [row[:] for row in grid]
    for r in range(top, bottom + 1):
        for c in range(left, right + 1):
            if (r in (top, bottom) or c in (left, right)) and out[r][c] == background:
                out[r][c] = 2

    def complete_runs(seq):
        runs = []
        i = 0
        while i < len(seq):
            if seq[i] == background:
                i += 1
                continue
            start = i
            while i < len(seq) and seq[i] != background:
                i += 1
            runs.append((start, i))
        if len(runs) > 1 and any(end - start >= 2 for start, end in runs):
            for (_, prev_end), (next_start, _) in zip(runs, runs[1:]):
                for j in range(prev_end, next_start):
                    if seq[j] == background:
                        yield j

    for r in range(h):
        for c in complete_runs(out[r]):
            out[r][c] = 2
    for c in range(w):
        column = [out[r][c] for r in range(h)]
        for r in complete_runs(column):
            out[r][c] = 2
    return out
'''
